vulnerable_code:
fastify.put('/iot/devices/:meterId/telemetry-interval', {
  schema: {
    params: {
      type: 'object',
      properties: {
        meterId: { type: 'string', pattern: '^[A-Z0-9_-]{8,16}$' }
      },
      required: ['meterId']
    },
    body: {
      type: 'object',
      properties: {
        intervalSeconds: { type: 'integer', minimum: 10, maximum: 86400 }
      },
      required: ['intervalSeconds']
    }
  },
  onRequest: [fastify.jwtVerify]
}, async (request, reply) => {
  const { meterId } = request.params;
  const { intervalSeconds } = request.body;

  const rows = await knex('smart_meters')
    .where({ hardware_id: meterId })
    .update({ reporting_interval_sec: intervalSeconds, updated_at: new Date() });

  if (!rows) return reply.status(404).send({ error: 'Smart meter not found' });
  return reply.send({ success: true, meterId, intervalSeconds });
});

corrected_code:
fastify.put('/iot/devices/:meterId/telemetry-interval', {
  schema: {
    params: {
      type: 'object',
      properties: {
        meterId: { type: 'string', pattern: '^[A-Z0-9_-]{8,16}$' }
      },
      required: ['meterId']
    },
    body: {
      type: 'object',
      properties: {
        intervalSeconds: { type: 'integer', minimum: 10, maximum: 86400 }
      },
      required: ['intervalSeconds']
    }
  },
  onRequest: [fastify.jwtVerify]
}, async (request, reply) => {
  const { meterId } = request.params;
  const { intervalSeconds } = request.body;

  const rows = await knex('smart_meters')
    .where({ hardware_id: meterId, account_id: request.user.accountId })
    .update({ reporting_interval_sec: intervalSeconds, updated_at: new Date() });

  if (!rows) return reply.status(403).send({ error: 'Smart meter not found or access denied' });
  return reply.send({ success: true, meterId, intervalSeconds });
});
